import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle: rejecting one document", () => {
  test("rejecting one extraction sends the whole vendor back", { tag: "@LIF-02" }, async ({ factory, apiAs }) => {
    // Arrange
    const { vendor, extractions } = await factory.vendorInReview();
    const reviewer = await apiAs("reviewer");
    const member = await apiAs("member");

    // Act
    const decision = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
      data: { decision: "reject", note: "Wrong counterparty" },
    });
    await expectStatus(decision, 200);

    // Assert
    const stored = await expectStatus<{ status: string }>(await member.get(`/api/vendors/${vendor.id}`), 200);
    expect(stored.status).toBe("rejected");

    const trail = await expectStatus<{ items: { action: string }[] }>(
      await member.get(`/api/vendors/${vendor.id}/audit`),
      200,
    );
    expect(trail.items.map((event) => event.action).slice(-2)).toEqual(["extraction.rejected", "vendor.rejected"]);
  });

  test("the rejected extraction stores the reviewer's note", { tag: "@LIF-02" }, async ({ factory, apiAs }) => {
    // Arrange
    const { documents, extractions } = await factory.vendorInReview();
    const reviewer = await apiAs("reviewer");

    // Act
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
        data: { decision: "reject", note: "Wrong counterparty" },
      }),
      200,
    );

    // Assert
    const stored = await factory.extraction(documents.contract.id, "reviewer");
    expect(stored.review_note).toBe("Wrong counterparty");
  });
});
